264	\begin{lemma}[Non-encoding support estimate]
265	\label{lem:qld-nonencoding-mass-bound}
266		\lean{MIPStarRE.QPBT.nonencodingMarginalMass}
267		\lean{MIPStarRE.QPBT.nonencodingMarginalMass_le}
268		\uses{def:s-w-marginals, def:qld-full-field-decoder, def:expanded-state,
269			lem:qld-4-7}
270		For either player and either Pauli basis, the non-encoding marginal mass in
271		Equation~\eqref{eq:qld-nonencoding-mass} is at most
272		$\delta_P^{\mathrm{supp}}=C_{\mathrm{supp}}B$ for a universal
273		$C_{\mathrm{supp}}\geq1$. This bound must be derived from point consistency and
274		Schwartz--Zippel; it is not an additional extraction hypothesis.
275	\end{lemma}
