277	% Following the source, the next lemma is stated after
278	% lem:qld-construct-the-paulis, whose proof invokes it; its own proof
279	% depends only on lem:qld-4-7 and lem:qld-comm-cons, so there is no
280	% circularity.
281	Lemmas~\ref{lem:qld-4-7} and~\ref{lem:qld-comm-cons} imply the following two estimates, which were used in the proof of Lemma~\ref{lem:qld-construct-the-paulis}.
282	
283	\begin{lemma}[The marginals absorb the point measurements]\label{lem:qld-constructing-the-paulis-helper}
284		\lean{MIPStarRE.QPBT.sum_marginalPoly_pointMeas_approx_id}
285		\lean{MIPStarRE.QPBT.marginalPoly_sub_pointMeas_approx_zero}
286		\leanok
287		\uses{def:s-w-marginals, def:expanded-point-measurement, def:expanded-state, def:povm-distance, lem:qld-4-7, def:symmetric-equivalents}
288		For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
289		\begin{equation}\label{eq:qld-sg-cons}
290			\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P^{\mathrm{id}}} \Id
291		\end{equation}
292		and
293		\begin{equation}\label{eq:qld-sg-cons2}
294			\bigl(\hat{S}^W_g \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)})\bigr)_{\mathrm{A}\mathrm{A}'} \approx_{\delta_P^{\mathrm{ann}}} 0\;,
295		\end{equation}
296		where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$. The independently quantified scale $\delta_P^{\mathrm{ann}}$ includes the additional point-measurement error in \eqref{eq:qld-sg-cons2}. Furthermore, all symmetric equivalents of these approximations also hold (Definition~\ref{def:symmetric-equivalents}).
297	\end{lemma}
298	\begin{proof}
299		\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
300		The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
301		\[
302			\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_G\;,
303		\]
304		which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_G$-consistent with $\Id$; Lemma~\ref{fact:agreement} and the universal-factor enlargement give the $\approx_{\delta_P}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G)} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
305		\[
306			(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
307		\]
308		Expanding
309		\[
310			\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
311			= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
312		\]
313		and bounding the right-hand side by $O(\delta_G + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} at scale $\delta_P$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
314	\end{proof}
